Use `pg`’s `Pool` and set timeouts at three layers:

- Pool acquisition timeout: `connectionTimeoutMillis`
- Idle connection timeout: `idleTimeoutMillis`
- Query timeout: per-query via `query_timeout` or wrapper logic
- Server-side statement timeout: `statement_timeout` in PostgreSQL

A solid baseline looks like this:

```bash
npm install pg
```

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: Number(process.env.PG_POOL_MAX ?? 10),
  min: Number(process.env.PG_POOL_MIN ?? 0),

  // Timeouts
  connectionTimeoutMillis: 5_000, // wait up to 5s for a new connection
  idleTimeoutMillis: 30_000,      // close idle clients after 30s

  // Optional safety
  allowExitOnIdle: false,

  // Keep long-dead TCP sessions from hanging forever
  keepAlive: true,

  // Applies to every statement on the server side
  statement_timeout: 10_000,      // cancel query after 10s in Postgres
  query_timeout: 10_000,          // client-side timeout in node-postgres
});

pool.on('error', (err) => {
  // Fired for idle clients when the backend dies or network breaks
  console.error('Unexpected PostgreSQL pool error', {
    message: err.message,
    stack: err.stack,
  });
});

async function query(text, params = []) {
  try {
    return await pool.query(text, params);
  } catch (err) {
    console.error('PostgreSQL query failed', {
      message: err.message,
      code: err.code,
      detail: err.detail,
    });
    throw err;
  }
}

async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } catch (err) {
    console.error('PostgreSQL client operation failed', {
      message: err.message,
      code: err.code,
    });
    throw err;
  } finally {
    client.release();
  }
}

async function shutdown() {
  await pool.end();
}

module.exports = {
  pool,
  query,
  withClient,
  shutdown,
};
```

Example usage:

```js
const { query, withClient } = require('./db');

async function getUser(id) {
  const result = await query(
    'SELECT id, email FROM users WHERE id = $1',
    [id]
  );
  return result.rows[0] ?? null;
}

async function createUserAndProfile(user, profile) {
  return withClient(async (client) => {
    await client.query('BEGIN');
    try {
      const userResult = await client.query(
        'INSERT INTO users(email) VALUES($1) RETURNING id',
        [user.email]
      );

      await client.query(
        'INSERT INTO profiles(user_id, bio) VALUES($1, $2)',
        [userResult.rows[0].id, profile.bio]
      );

      await client.query('COMMIT');
      return userResult.rows[0];
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    }
  });
}
```

For process shutdown:

```js
const { shutdown } = require('./db');

process.on('SIGINT', async () => {
  await shutdown();
  process.exit(0);
});

process.on('SIGTERM', async () => {
  await shutdown();
  process.exit(0);
});
```

Recommended defaults for a typical API service:

- `max`: `10` to `20` per app instance
- `connectionTimeoutMillis`: `3000` to `5000`
- `idleTimeoutMillis`: `30000`
- `statement_timeout`: `5000` to `15000`

Important points:

- Don’t create a new `Pool` per request. Create one singleton pool for the process.
- Always `release()` clients in `finally`.
- Prefer `pool.query(...)` for simple queries; use `pool.connect()` only for transactions or session-specific work.
- Keep pool size conservative. If you run many app instances, total connections can overwhelm Postgres.
- Timeouts should fail fast enough to protect the app, but not so fast that normal queries get cancelled.

