Use `pg`’s `Pool`. Configure three timeout layers:

- `connectionTimeoutMillis`: fail fast if a connection cannot be acquired/opened
- `idleTimeoutMillis`: close unused clients
- `statement_timeout` / `query_timeout`: stop slow queries instead of hanging forever

Example:

```bash
npm install pg
```

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,
  min: 2,

  // Connection lifecycle
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 5_000,
  allowExitOnIdle: false,

  // Query safety
  statement_timeout: 10_000,
  query_timeout: 10_000,
  idle_in_transaction_session_timeout: 15_000,

  // SSL for hosted Postgres if needed
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// Fired when an idle pooled client dies unexpectedly
pool.on('error', (err) => {
  console.error('Unexpected idle PostgreSQL client error', err);
});

async function query(text, params) {
  try {
    return await pool.query(text, params);
  } catch (err) {
    console.error('PostgreSQL query failed', {
      message: err.message,
      code: err.code,
      detail: err.detail,
    });
    throw err;
  }
}

async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } catch (err) {
    console.error('PostgreSQL client operation failed', {
      message: err.message,
      code: err.code,
    });
    throw err;
  } finally {
    client.release();
  }
}

async function shutdown() {
  await pool.end();
}

module.exports = {
  pool,
  query,
  withClient,
  shutdown,
};
```

