```js
const { shutdown } = require('./db');

async function stop(signal) {
  console.log(`${signal} received, closing PostgreSQL pool`);
  try {
    await shutdown();
    process.exit(0);
  } catch (err) {
    console.error('Failed to close PostgreSQL pool', err);
    process.exit(1);
  }
}

process.on('SIGINT', () => stop('SIGINT'));
