Use `pg` pool. Set 4 knobs: `connectionTimeoutMillis`, `idleTimeoutMillis`, `max`, `maxLifetimeSeconds`. Add pool-level error listener. Wrap query with retry only for safe/idempotent work.

```bash
npm install pg
```

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // pool sizing
  max: 20,                  // max clients in pool
  min: 2,                   // keep few warm if using pg >= 8.11
  idleTimeoutMillis: 30_000, // close idle client after 30s

  // connect / lifecycle timeouts
  connectionTimeoutMillis: 5_000, // fail fast if DB unreachable
  maxLifetimeSeconds: 300,        // rotate clients every 5m

  // TLS example for managed Postgres
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,

  // optional app label
  application_name: 'my-node-api',
});

pool.on('error', (err) => {
  // idle client error. Important: process likely unhealthy.
  console.error('Unexpected error on idle PostgreSQL client', err);
});

async function query(text, params, { timeoutMs = 10_000 } = {}) {
  const client = await pool.connect();
  try {
    await client.query(`SET statement_timeout = ${timeoutMs}`);
    return await client.query(text, params);
  } catch (err) {
    console.error('PostgreSQL query failed', {
      message: err.message,
      code: err.code,
      detail: err.detail,
    });
    throw err;
  } finally {
    client.release();
  }
}

async function withTransaction(fn, { timeoutMs = 15_000 } = {}) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(`SET LOCAL statement_timeout = ${timeoutMs}`);
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackErr) {
      console.error('Rollback failed', rollbackErr);
    }
    throw err;
  } finally {
    client.release();
  }
}

async function shutdown() {
  await pool.end();
}

module.exports = { pool, query, withTransaction, shutdown };
```

Usage:

```js
