Use `pg` and create one shared `Pool` for process. Set three timeout layers:

- `connectionTimeoutMillis`: fail fast if pool cannot open/get connection
- `idleTimeoutMillis`: close idle clients
- query timeout: stop slow statements
- optionally server-side `statement_timeout` so DB enforces it too

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,                    // tune per app/db size
  min: 2,
  idleTimeoutMillis: 30_000,  // close idle clients after 30s
  connectionTimeoutMillis: 5_000, // wait max 5s for connect
  maxLifetimeSeconds: 300,    // recycle connections every 5 min
  allowExitOnIdle: false,
  application_name: 'my-node-app',
});

pool.on('error', (err) => {
  // background idle client error
  console.error('Unexpected PostgreSQL pool error', err);
});

async function query(text, params, opts = {}) {
  const client = await pool.connect();
  try {
    if (opts.statementTimeoutMs) {
      await client.query(`SET LOCAL statement_timeout = ${Number(opts.statementTimeoutMs)}`);
    }
    return await client.query({
      text,
      values: params,
      query_timeout: opts.queryTimeoutMs ?? 10_000, // client-side timeout
    });
  } catch (err) {
    console.error('PostgreSQL query failed', {
      message: err.message,
      code: err.code,
      text,
    });
    throw err;
  } finally {
    client.release();
  }
}

async function closePool() {
  await pool.end();
}

process.on('SIGINT', async () => {
  await closePool();
  process.exit(0);
});

process.on('SIGTERM', async () => {
  await closePool();
  process.exit(0);
});

module.exports = { pool, query, closePool };
```

